// Vector glyphs for component icons (24-unit grid, centred on the origin), shared by
// the 2D fallback renderer and the 3D film's icon textures.
import { TAU } from './util.js';

// ── Paths ───────────────────────────────────────────────────────────────────
export const rr = (g, x, y, w, h, r) => {
  g.beginPath();
  g.roundRect(x, y, w, h, Math.min(r, w / 2, h / 2));
};
export const circle = (g, x, y, r) => {
  g.beginPath();
  g.arc(x, y, r, 0, TAU);
};
export const polyline = (g, pts) => {
  g.beginPath();
  pts.forEach(([x, y], i) => (i ? g.lineTo(x, y) : g.moveTo(x, y)));
};

// White glyphs on a 24-unit grid centred at the origin (drawn inside the coloured tile).
export const GLYPHS = {
  window: (g) => {
    rr(g, -9, -7.5, 18, 15, 2.6);
    g.stroke();
    polyline(g, [[-9, -2.8], [9, -2.8]]);
    g.stroke();
  },
  desktop: (g) => {
    rr(g, -9.5, -8, 19, 12.5, 2.2);
    g.stroke();
    polyline(g, [[0, 4.5], [0, 8]]);
    g.stroke();
    polyline(g, [[-4, 8.2], [4, 8.2]]);
    g.stroke();
  },
  globe: (g) => {
    circle(g, 0, 0, 8.6);
    g.stroke();
    g.beginPath();
    g.ellipse(0, 0, 3.8, 8.6, 0, 0, TAU);
    g.stroke();
    polyline(g, [[-8.6, 0], [8.6, 0]]);
    g.stroke();
  },
  route: (g) => {
    g.beginPath();
    g.moveTo(-9, 0);
    g.lineTo(-2, 0);
    g.bezierCurveTo(1.5, 0, 2.5, -6, 7.5, -6);
    g.moveTo(-2, 0);
    g.bezierCurveTo(1.5, 0, 2.5, 6, 7.5, 6);
    g.stroke();
    polyline(g, [[5, -8.5], [8, -6], [5, -3.5]]);
    g.stroke();
    polyline(g, [[5, 3.5], [8, 6], [5, 8.5]]);
    g.stroke();
  },
  hex: (g) => {
    g.beginPath();
    for (let k = 0; k < 6; k++) {
      const a = (k / 6) * TAU - Math.PI / 2;
      k ? g.lineTo(8.6 * Math.cos(a), 8.6 * Math.sin(a)) : g.moveTo(8.6 * Math.cos(a), 8.6 * Math.sin(a));
    }
    g.closePath();
    g.stroke();
    circle(g, 0, 0, 2.4);
    g.fill();
  },
  tag: (g) => {
    g.beginPath();
    g.moveTo(-8.5, -8.5);
    g.lineTo(0, -8.5);
    g.lineTo(8.5, 0);
    g.lineTo(0, 8.5);
    g.lineTo(-8.5, 0);
    g.closePath();
    g.stroke();
    circle(g, -3.8, -3.8, 1.8);
    g.fill();
  },
  grid: (g) => {
    [[-8.5, -8.5], [1.5, -8.5], [-8.5, 1.5], [1.5, 1.5]].forEach(([x, y]) => {
      rr(g, x, y, 7, 7, 1.8);
      g.stroke();
    });
  },
  search: (g) => {
    circle(g, -2, -2, 6);
    g.stroke();
    polyline(g, [[2.5, 2.5], [8, 8]]);
    g.stroke();
  },
  link: (g) => {
    g.save();
    g.rotate(-Math.PI / 4);
    rr(g, -9.5, -3.6, 11, 7.2, 3.6);
    g.stroke();
    rr(g, -1.5, -3.6, 11, 7.2, 3.6);
    g.stroke();
    g.restore();
  },
  wave: (g) => {
    g.beginPath();
    for (let x = -9; x <= 9; x += 0.5) {
      const y = Math.sin((x / 9) * Math.PI * 1.5) * 5;
      x === -9 ? g.moveTo(x, y) : g.lineTo(x, y);
    }
    g.stroke();
  },
  gauge: (g) => {
    g.beginPath();
    g.arc(0, 2.5, 8.5, Math.PI * 0.9, Math.PI * 2.1);
    g.stroke();
    polyline(g, [[0, 2.5], [4.5, -3]]);
    g.stroke();
    circle(g, 0, 2.5, 1.8);
    g.fill();
  },
  cylinder: (g) => {
    g.beginPath();
    g.ellipse(0, -6, 8, 2.8, 0, 0, TAU);
    g.stroke();
    g.beginPath();
    g.moveTo(-8, -6);
    g.lineTo(-8, 6);
    g.ellipse(0, 6, 8, 2.8, 0, Math.PI, 0, true);
    g.lineTo(8, -6);
    g.stroke();
    g.beginPath();
    g.ellipse(0, 0, 8, 2.8, 0, Math.PI, 0, true);
    g.stroke();
  },
  bolt: (g) => {
    g.beginPath();
    g.moveTo(2, -9.5);
    g.lineTo(-6.5, 1.5);
    g.lineTo(-0.5, 1.5);
    g.lineTo(-2, 9.5);
    g.lineTo(6.5, -1.5);
    g.lineTo(0.5, -1.5);
    g.closePath();
    g.fill();
  },
  queue: (g) => {
    [-6, 0, 6].forEach((y, k) => {
      rr(g, -9 + k * 1.5, y - 2, 13, 4, 2);
      g.stroke();
    });
    polyline(g, [[6.5, -3], [9.5, 0], [6.5, 3]]);
    g.stroke();
  },
  gear: (g) => {
    g.beginPath();
    for (let k = 0; k <= 16; k++) {
      const a = (k / 16) * TAU;
      const r = k % 2 ? 6.4 : 8.8;
      k ? g.lineTo(r * Math.cos(a), r * Math.sin(a)) : g.moveTo(r * Math.cos(a), r * Math.sin(a));
    }
    g.closePath();
    g.stroke();
    circle(g, 0, 0, 2.6);
    g.stroke();
  },
  lambda: (g) => {
    g.beginPath();
    g.moveTo(-6.5, -8.5);
    g.lineTo(-3, -8.5);
    g.lineTo(6.5, 8.5);
    g.moveTo(0.2, -2.5);
    g.lineTo(-6, 8.5);
    g.stroke();
  },
  table: (g) => {
    rr(g, -9, -7.5, 18, 15, 2.4);
    g.stroke();
    polyline(g, [[-9, -2.5], [9, -2.5]]);
    g.stroke();
    polyline(g, [[-2.5, -2.5], [-2.5, 7.5]]);
    g.stroke();
  },
  plug: (g) => {
    polyline(g, [[-3.2, -9], [-3.2, -4]]);
    g.stroke();
    polyline(g, [[3.2, -9], [3.2, -4]]);
    g.stroke();
    rr(g, -6.5, -4, 13, 7, 2.5);
    g.stroke();
    polyline(g, [[0, 3], [0, 9]]);
    g.stroke();
  },
  sliders: (g) => {
    [[-5.5, -2.5], [0, 3.5], [5.5, -4.5]].forEach(([x, y]) => {
      polyline(g, [[x, -8.5], [x, 8.5]]);
      g.stroke();
      circle(g, x, y, 2.4);
      g.fill();
    });
  },
  branch: (g) => {
    polyline(g, [[-4.5, -4], [-4.5, 4]]);
    g.stroke();
    g.beginPath();
    g.moveTo(5, -1.5);
    g.bezierCurveTo(5, 3, -4.5, 1.5, -4.5, 5);
    g.stroke();
    [[-4.5, -6.5], [-4.5, 6.8], [5, -4]].forEach(([x, y]) => {
      circle(g, x, y, 2.4);
      g.stroke();
    });
  },
  pipeline: (g) => {
    polyline(g, [[-6, 0], [6, 0]]);
    g.stroke();
    [-7, 0, 7].forEach((x) => {
      circle(g, x, 0, 2.6);
      g.fill();
    });
  },
  check: (g) => {
    polyline(g, [[-7, 0.5], [-2.2, 5.5], [7.5, -5.5]]);
    g.stroke();
  },
  box: (g) => {
    g.beginPath();
    g.moveTo(0, -9);
    g.lineTo(8, -4.5);
    g.lineTo(8, 4.5);
    g.lineTo(0, 9);
    g.lineTo(-8, 4.5);
    g.lineTo(-8, -4.5);
    g.closePath();
    g.moveTo(-8, -4.5);
    g.lineTo(0, 0);
    g.lineTo(8, -4.5);
    g.moveTo(0, 0);
    g.lineTo(0, 9);
    g.stroke();
  },
  layers: (g) => {
    g.beginPath();
    g.moveTo(0, -8.5);
    g.lineTo(8.5, -4);
    g.lineTo(0, 0.5);
    g.lineTo(-8.5, -4);
    g.closePath();
    g.stroke();
    polyline(g, [[-8.5, 0.5], [0, 5], [8.5, 0.5]]);
    g.stroke();
    polyline(g, [[-8.5, 4.5], [0, 9], [8.5, 4.5]]);
    g.stroke();
  },
  chart: (g) => {
    [[-8, 1, 5], [-2.5, -6, 12], [3, -2, 8]].forEach(([x, y, h]) => {
      rr(g, x, y, 4.2, h + 1, 1.4);
      g.fill();
    });
  },
  pulse: (g) => {
    polyline(g, [[-9.5, 0.5], [-4.5, 0.5], [-2, -6.5], [1.5, 7], [4, 0.5], [9.5, 0.5]]);
    g.stroke();
  },
  list: (g) => {
    [-5.5, 0, 5.5].forEach((y) => {
      circle(g, -6.5, y, 1.5);
      g.fill();
      polyline(g, [[-2.5, y], [8.5, y]]);
      g.stroke();
    });
  },
  cloud: (g) => {
    g.beginPath();
    g.moveTo(-7, 6);
    g.bezierCurveTo(-11, 6, -11, 0, -6.5, -0.5);
    g.bezierCurveTo(-6, -6, 2, -8, 4, -2.5);
    g.bezierCurveTo(9, -3, 11, 6, 6, 6);
    g.closePath();
    g.stroke();
  },
  phone: (g) => {
    rr(g, -5.5, -9.5, 11, 19, 2.8);
    g.stroke();
    polyline(g, [[-1.8, 6.4], [1.8, 6.4]]);
    g.stroke();
  },
  bubble: (g) => {
    g.beginPath();
    g.moveTo(-6, -7.5);
    g.lineTo(6, -7.5);
    g.quadraticCurveTo(9, -7.5, 9, -4.5);
    g.lineTo(9, 1.5);
    g.quadraticCurveTo(9, 4.5, 6, 4.5);
    g.lineTo(-1, 4.5);
    g.lineTo(-5.5, 8.5);
    g.lineTo(-5, 4.5);
    g.lineTo(-6, 4.5);
    g.quadraticCurveTo(-9, 4.5, -9, 1.5);
    g.lineTo(-9, -4.5);
    g.quadraticCurveTo(-9, -7.5, -6, -7.5);
    g.closePath();
    g.stroke();
  },
  send: (g) => {
    g.beginPath();
    g.moveTo(-9, -1);
    g.lineTo(9, -8);
    g.lineTo(3, 9);
    g.lineTo(0, 2);
    g.closePath();
    g.stroke();
    polyline(g, [[0, 2], [9, -8]]);
    g.stroke();
  },
  key: (g) => {
    circle(g, -4, 0, 4.5);
    g.stroke();
    polyline(g, [[0.5, 0], [9, 0], [9, 3.5]]);
    g.stroke();
    polyline(g, [[5.5, 0], [5.5, 2.8]]);
    g.stroke();
  },
  lock: (g) => {
    rr(g, -7.5, -1.5, 15, 10.5, 2.4);
    g.stroke();
    g.beginPath();
    g.moveTo(-4.5, -1.5);
    g.lineTo(-4.5, -4.5);
    g.arc(0, -4.5, 4.5, Math.PI, 0);
    g.lineTo(4.5, -1.5);
    g.stroke();
    circle(g, 0, 3.8, 1.6);
    g.fill();
  },
  image: (g) => {
    rr(g, -9, -7.5, 18, 15, 2.4);
    g.stroke();
    polyline(g, [[-9, 5], [-3, -1], [2, 4], [4.5, 1.5], [9, 6]]);
    g.stroke();
    circle(g, 4, -3, 1.8);
    g.fill();
  },
  people: (g) => {
    circle(g, -3.5, -3.5, 3);
    g.stroke();
    circle(g, 4.5, -2.5, 2.4);
    g.stroke();
    g.beginPath();
    g.moveTo(-9.5, 8);
    g.quadraticCurveTo(-9, 1.5, -3.5, 1.5);
    g.quadraticCurveTo(2, 1.5, 2.5, 8);
    g.stroke();
    g.beginPath();
    g.moveTo(3.5, 2.5);
    g.quadraticCurveTo(9, 2.5, 9.5, 7.5);
    g.stroke();
  },
  bell: (g) => {
    g.beginPath();
    g.moveTo(-7, 4.5);
    g.quadraticCurveTo(-5.5, 3, -5.5, -1);
    g.quadraticCurveTo(-5.5, -7.5, 0, -7.5);
    g.quadraticCurveTo(5.5, -7.5, 5.5, -1);
    g.quadraticCurveTo(5.5, 3, 7, 4.5);
    g.closePath();
    g.stroke();
    polyline(g, [[-2, 7.5], [2, 7.5]]);
    g.stroke();
  },
  shield: (g) => {
    g.beginPath();
    g.moveTo(0, -9);
    g.lineTo(7.5, -6);
    g.lineTo(7.5, 0);
    g.quadraticCurveTo(7.5, 6.5, 0, 9.5);
    g.quadraticCurveTo(-7.5, 6.5, -7.5, 0);
    g.lineTo(-7.5, -6);
    g.closePath();
    g.stroke();
    polyline(g, [[-3.2, 0.5], [-0.8, 3], [3.8, -2]]);
    g.stroke();
  },
  person: (g) => {
    circle(g, 0, -3.5, 3.6);
    g.stroke();
    g.beginPath();
    g.moveTo(-7.5, 8.5);
    g.quadraticCurveTo(-7, 1.5, 0, 1.5);
    g.quadraticCurveTo(7, 1.5, 7.5, 8.5);
    g.stroke();
  },
  inbox: (g) => {
    g.beginPath();
    g.moveTo(-9, 1);
    g.lineTo(-6, -7);
    g.lineTo(6, -7);
    g.lineTo(9, 1);
    g.lineTo(9, 7.5);
    g.lineTo(-9, 7.5);
    g.closePath();
    g.stroke();
    polyline(g, [[-9, 1], [-3.5, 1], [-2, 3.5], [2, 3.5], [3.5, 1], [9, 1]]);
    g.stroke();
  },
  helm: (g) => {
    circle(g, 0, 0, 7.5);
    g.stroke();
    for (let k = 0; k < 7; k++) {
      const a = (k / 7) * TAU - Math.PI / 2;
      polyline(g, [[2.6 * Math.cos(a), 2.6 * Math.sin(a)], [9.5 * Math.cos(a), 9.5 * Math.sin(a)]]);
      g.stroke();
    }
  },
};
