// Screen-space typography, drawn on a 2D canvas over the rendered frame and styled as
// Liquid Glass so it matches the page's controls: the developer's name tag (every cut), and
// for the film cut the corner mark, a caption per stage and the contact end card.
import { STAGES, T } from './timeline.js';
import { clamp, ease, prog } from './util.js';
import { stageAt } from './graph.js';
import { rr } from './glyphs.js';
import { drawLogo, HANDLE, ROLE } from './brand.js';

const F = {
  display: '-apple-system, BlinkMacSystemFont, "SF Pro Display", "Geist", "Helvetica Neue", Arial, sans-serif',
  text: '-apple-system, BlinkMacSystemFont, "SF Pro Text", "Geist", "Helvetica Neue", Arial, sans-serif',
};
const INK = '#1d1d1f';
const INK3 = '#6e6e73';
const INK4 = '#86868b';
const BLUE = '#0071e3';

const text = (g, str, x, y, { size, weight = 400, family = F.text, color = INK, align = 'left', alpha = 1, tracking = 0 }) => {
  if (alpha <= 0.001) return 0;
  g.globalAlpha = alpha;
  g.font = `${weight} ${size}px ${family}`;
  g.fillStyle = color;
  g.textAlign = align;
  g.textBaseline = 'alphabetic';
  if ('letterSpacing' in g) g.letterSpacing = `${tracking}px`;
  g.fillText(str, x, y);
  const w = g.measureText(str).width;
  if ('letterSpacing' in g) g.letterSpacing = '0px';
  g.globalAlpha = 1;
  return w;
};
const measure = (g, str, size, weight = 400, family = F.text) => {
  g.font = `${weight} ${size}px ${family}`;
  return g.measureText(str).width;
};
const rise = (t, at, dur = 0.7) => {
  const p = ease.outCubic(prog(t, at, at + dur));
  return { a: p, dy: (1 - p) * 14 };
};

// A Liquid Glass capsule: bright translucent body, specular rim, soft shadow.
export const glassCapsule = (g, x, y, w, h, alpha = 1, u = 1) => {
  if (alpha <= 0.001) return;
  const r = h / 2;
  g.save();
  g.globalAlpha = alpha;
  g.shadowColor = 'rgba(0,0,0,0.10)';
  g.shadowBlur = 24 * u;
  g.shadowOffsetY = 8 * u;
  rr(g, x, y, w, h, r);
  g.fillStyle = 'rgba(255,255,255,0.62)';
  g.fill();
  g.shadowColor = 'transparent';
  const sheen = g.createLinearGradient(0, y, 0, y + h);
  sheen.addColorStop(0, 'rgba(255,255,255,0.75)');
  sheen.addColorStop(0.45, 'rgba(255,255,255,0.15)');
  sheen.addColorStop(1, 'rgba(255,255,255,0.35)');
  rr(g, x, y, w, h, r);
  g.fillStyle = sheen;
  g.fill();
  rr(g, x + 0.75 * u, y + 0.75 * u, w - 1.5 * u, h - 1.5 * u, r);
  g.lineWidth = 1.5 * u;
  const rim = g.createLinearGradient(x, y, x + w * 0.4, y + h);
  rim.addColorStop(0, 'rgba(255,255,255,1)');
  rim.addColorStop(0.5, 'rgba(255,255,255,0.35)');
  rim.addColorStop(1, 'rgba(255,255,255,0.8)');
  g.strokeStyle = rim;
  g.stroke();
  rr(g, x, y, w, h, r);
  g.lineWidth = 1 * u;
  g.strokeStyle = 'rgba(0,0,0,0.08)';
  g.stroke();
  g.restore();
};

export const loadTitleFonts = () =>
  Promise.all(['400 20px Geist', '500 20px Geist', '600 20px Geist', '700 20px Geist'].map((f) => document.fonts.load(f, 'AaİŞĞ·—0'))).catch(() => {});

// The developer's name tag: a glass callout pointing at (ax, ay), like a multiplayer cursor.
// A green presence dot on the mark; a typing bubble while he types; the mark glows as a
// deploy leaves his screen.
export const drawNameTag = (g, ax, ay, u, { alpha = 1, pop = 1, typing = 0, glow = 0, t = 0, cw = 1920 }) => {
  if (alpha <= 0.001) return;
  const H = 58 * u;
  const logo = 40 * u;
  const padL = 9 * u;
  const gap = 11 * u;
  const nameSize = 20 * u;
  const roleSize = 15.5 * u;
  const w = padL + logo + gap + Math.max(measure(g, HANDLE, nameSize, 600, F.display), measure(g, ROLE, roleSize, 500)) + 22 * u;
  const margin = 18 * u;
  const tail = 10 * u;
  const x = clamp(ax - w / 2, margin, cw - margin - w);
  const y = ay - tail - H;
  const tx = clamp(ax, x + H * 0.6, x + w - H * 0.6);
  g.save();
  g.translate(ax, ay);
  g.scale(Math.max(0.01, pop), Math.max(0.01, pop));
  g.translate(-ax, -ay);
  // Tail, then the capsule over its root.
  g.save();
  g.globalAlpha = alpha;
  g.shadowColor = 'rgba(0,0,0,0.10)';
  g.shadowBlur = 10 * u;
  g.shadowOffsetY = 3 * u;
  g.beginPath();
  g.moveTo(tx - 11 * u, y + H - 3 * u);
  g.quadraticCurveTo(tx - 2.5 * u, y + H + 1 * u, tx, ay);
  g.quadraticCurveTo(tx + 2.5 * u, y + H + 1 * u, tx + 11 * u, y + H - 3 * u);
  g.closePath();
  g.fillStyle = 'rgba(255,255,255,0.8)';
  g.fill();
  g.restore();
  glassCapsule(g, x, y, w, H, alpha, u);
  const lx = x + padL;
  const ly = y + (H - logo) / 2;
  if (glow > 0.01) {
    g.save();
    g.globalAlpha = alpha * glow;
    g.shadowColor = 'rgba(10,132,255,0.9)';
    g.shadowBlur = 26 * u;
    rr(g, lx + 2 * u, ly + 2 * u, logo - 4 * u, logo - 4 * u, 10 * u);
    g.fillStyle = '#0a84ff';
    g.fill();
    g.restore();
  }
  drawLogo(g, lx, ly, logo, { alpha });
  // Presence: online.
  g.save();
  g.globalAlpha = alpha;
  g.beginPath();
  g.arc(lx + logo - 2 * u, ly + logo - 2 * u, 6.5 * u, 0, Math.PI * 2);
  g.fillStyle = '#fff';
  g.fill();
  g.beginPath();
  g.arc(lx + logo - 2 * u, ly + logo - 2 * u, 4.5 * u, 0, Math.PI * 2);
  g.fillStyle = '#34c759';
  g.fill();
  g.restore();
  const tx0 = lx + logo + gap;
  text(g, HANDLE, tx0, y + 27 * u, { size: nameSize, weight: 600, family: F.display, alpha, tracking: -0.2 * u });
  text(g, ROLE, tx0, y + 46 * u, { size: roleSize, weight: 500, color: INK3, alpha });
  // Typing… bubble, beside the tag.
  if (typing > 0.01) {
    const bw = 64 * u;
    const bh = 36 * u;
    const right = x + w + 10 * u + bw < cw - margin;
    const bx = right ? x + w + 10 * u : x - 10 * u - bw;
    const by = y + (H - bh) / 2;
    const k = Math.max(0.01, ease.outBack(typing));
    const ox = right ? bx : bx + bw;
    g.save();
    g.translate(ox, by + bh / 2);
    g.scale(k, k);
    g.translate(-ox, -(by + bh / 2));
    glassCapsule(g, bx, by, bw, bh, alpha * Math.min(1, typing * 1.5), u);
    for (let i = 0; i < 3; i++) {
      const b = Math.max(0, Math.sin(t * 10 - i * 1.15));
      g.globalAlpha = alpha * Math.min(1, typing * 1.5) * (0.35 + 0.65 * b);
      g.beginPath();
      g.arc(bx + bw / 2 + (i - 1) * 13 * u, by + bh / 2 - 2.5 * u * b, 4.6 * u, 0, Math.PI * 2);
      g.fillStyle = INK4;
      g.fill();
    }
    g.restore();
  }
  g.restore();
};

export const drawTitles = (g, t, cw, ch, portrait) => {
  const u = Math.min(cw, ch) / 1080;
  const m = 64 * u;
  g.save();
  // The mark in the corner, as on a broadcast.
  const idA = prog(t, T.identityIn, T.identityIn + 0.8, ease.outCubic) * (1 - prog(t, T.identityOut, T.identityOut + 0.5));
  if (idA > 0) drawLogo(g, m - 6 * u, (portrait ? 70 : 50) * u, 46 * u, { alpha: idA * 0.95 });

  // Stage caption in a glass capsule: step, title, the technologies it adds.
  const si = stageAt(t);
  if (si >= 0 && t < T.identityOut + 0.4) {
    const s = STAGES[si];
    const next = STAGES[si + 1]?.at ?? T.identityOut;
    const r = rise(t, s.at + 0.12, 0.6);
    const out = prog(t, next - 0.1, next + 0.15);
    const a = r.a * (1 - out) * (1 - prog(t, T.identityOut, T.identityOut + 0.4));
    if (a > 0) {
      const num = `${String(si + 1).padStart(2, '0')}`;
      const of = ` / ${String(STAGES.length).padStart(2, '0')}`;
      const titleSize = (portrait ? 30 : 28) * u;
      const detailSize = (portrait ? 23 : 22) * u;
      const pad = 24 * u;
      const numW = measure(g, num, 20 * u, 600) + measure(g, of, 20 * u, 500);
      const tW = measure(g, s.title, titleSize, 600, F.display);
      const dW = measure(g, s.detail, detailSize);
      const h = (portrait ? 118 : 76) * u;
      const w = portrait ? Math.max(numW, tW, dW) + pad * 2 : numW + tW + dW + pad * 2 + 40 * u;
      const x = m - pad * 0.6;
      const y = ch - (portrait ? 96 : 60) * u - h + r.dy * u;
      glassCapsule(g, x, y, Math.min(w, cw - x * 2), h, a, u);
      if (portrait) {
        const nx = x + pad;
        const nw = text(g, num, nx, y + 38 * u, { size: 20 * u, weight: 600, color: BLUE, alpha: a });
        text(g, of, nx + nw, y + 38 * u, { size: 20 * u, weight: 500, color: INK4, alpha: a });
        text(g, s.title, nx, y + 74 * u, { size: titleSize, weight: 600, family: F.display, alpha: a, tracking: -0.3 * u });
        text(g, s.detail, nx, y + 104 * u, { size: detailSize, color: INK3, alpha: a });
      } else {
        const base = y + h / 2 + 9 * u;
        let cx = x + pad;
        cx += text(g, num, cx, base, { size: 20 * u, weight: 600, color: BLUE, alpha: a });
        cx += text(g, of, cx, base, { size: 20 * u, weight: 500, color: INK4, alpha: a }) + 20 * u;
        cx += text(g, s.title, cx, base, { size: titleSize, weight: 600, family: F.display, alpha: a, tracking: -0.3 * u }) + 16 * u;
        text(g, s.detail, cx, base, { size: detailSize, color: INK3, alpha: a });
      }
    }
  }

  // End card: the mark and handle, the full name, and how to get in touch.
  if (t >= T.endcard - 0.1) {
    const cx = cw / 2;
    const y0 = ch * (portrait ? 0.37 : 0.36);
    const n = rise(t, T.endcard + 0.1, 0.8);
    const logo = (portrait ? 104 : 92) * u;
    const wordSize = (portrait ? 76 : 68) * u;
    const ww = measure(g, HANDLE, wordSize, 700, F.display);
    const lockW = logo + 24 * u + ww;
    const lx = cx - lockW / 2;
    const ly = y0 - logo / 2 + n.dy * u;
    g.save();
    g.globalAlpha = n.a;
    g.shadowColor = 'rgba(0,0,0,0.22)';
    g.shadowBlur = 30 * u;
    g.shadowOffsetY = 10 * u;
    rr(g, lx + 4 * u, ly + 4 * u, logo - 8 * u, logo - 8 * u, logo * 0.22);
    g.fillStyle = '#1d1d1f';
    g.fill();
    g.restore();
    drawLogo(g, lx, ly, logo, { alpha: n.a });
    text(g, HANDLE, lx + logo + 24 * u, y0 + wordSize * 0.36 + n.dy * u, { size: wordSize, weight: 700, family: F.display, alpha: n.a, tracking: -1.6 * u });
    const ty = y0 + logo / 2 + (portrait ? 78 : 66) * u;
    const r1 = rise(t, T.endcard + 0.4, 0.8);
    text(g, `Irfan Can Kaleli  ·  ${ROLE}`, cx, ty + r1.dy * u, { size: (portrait ? 34 : 32) * u, weight: 500, color: INK3, align: 'center', alpha: r1.a });
    const r2 = rise(t, T.endcard + 0.52, 0.8);
    text(g, 'Ounass  ·  Kargo  ·  Onbiron R&D', cx, ty + (portrait ? 56 : 50) * u + r2.dy * u, { size: (portrait ? 27 : 24) * u, weight: 500, color: INK4, align: 'center', alpha: r2.a });
    const pills = ['irfanck.com', 'irfancnkaleli@gmail.com', 'linkedin.com/in/irfan-can-kaleli'];
    const size = (portrait ? 28 : 24) * u;
    const widths = pills.map((p) => measure(g, p, size, 500) + 48 * u);
    const ph = size * 2.2;
    const gap = 14 * u;
    const py = ty + (portrait ? 116 : 104) * u;
    const rowW = widths.reduce((a, b) => a + b, 0) + gap * (pills.length - 1);
    let px = cx - rowW / 2;
    pills.forEach((p, i) => {
      const r = rise(t, T.endcard + 0.68 + i * 0.1, 0.7);
      const x = portrait ? cx - widths[i] / 2 : px;
      const y = (portrait ? py + i * (ph + gap) : py) + r.dy * u;
      glassCapsule(g, x, y, widths[i], ph, r.a, u);
      text(g, p, x + widths[i] / 2, y + ph / 2 + size * 0.36, { size, weight: 500, color: i ? INK : BLUE, align: 'center', alpha: r.a });
      px += widths[i] + gap;
    });
  }
  g.restore();
};
