// The iK mark — Irfan Can Kaleli's logo: a graphite tile where the "i" doubles as the
// upright of a "K", its arms a blue chevron. Drawn identically in the film (name tag,
// chair, corner mark, end card) and matching favicon.svg and the nav mark on the page.
//
// Geometry lives on a 64-unit grid.
export const drawLogo = (g, x, y, size, { tile = true, alpha = 1 } = {}) => {
  if (alpha <= 0.001) return;
  const k = size / 64;
  g.save();
  g.globalAlpha *= alpha;
  g.translate(x, y);
  g.scale(k, k);
  if (tile) {
    const body = g.createLinearGradient(0, 0, 0, 64);
    body.addColorStop(0, '#2c2c30');
    body.addColorStop(1, '#0b0b0d');
    g.beginPath();
    g.roundRect(0, 0, 64, 64, 16);
    g.fillStyle = body;
    g.fill();
    g.beginPath();
    g.roundRect(0.5, 0.5, 63, 63, 15.5);
    g.strokeStyle = 'rgba(255,255,255,0.14)';
    g.lineWidth = 1;
    g.stroke();
  }
  g.lineWidth = 6.6;
  g.lineCap = 'round';
  g.lineJoin = 'round';
  g.fillStyle = '#fff';
  g.strokeStyle = '#fff';
  g.beginPath();
  g.arc(22.5, 17.5, 4.4, 0, Math.PI * 2);
  g.fill();
  g.beginPath();
  g.moveTo(22.5, 27);
  g.lineTo(22.5, 47);
  g.stroke();
  const arms = g.createLinearGradient(27.8, 19, 41.5, 47);
  arms.addColorStop(0, '#6ad4ff');
  arms.addColorStop(1, '#0a7cff');
  g.strokeStyle = arms;
  g.beginPath();
  g.moveTo(41.5, 19);
  g.lineTo(27.8, 33);
  g.lineTo(41.5, 47);
  g.stroke();
  g.restore();
};

export const HANDLE = 'IrfanK';
